    setBotAnswers(nextAnswers);

    if (botStep === botQuestions.length - 1) {
      buildBotRecommendations(nextAnswers);
      setBotStep(botQuestions.length);
      return;
    }

    setBotStep((prev) => prev + 1);
  };

